<script setup lang="ts">
import { ref, onMounted } from 'vue'
import { getDietRecords, addDietRecord, deleteDietRecord, getExerciseRecords, addExerciseRecord, deleteExerciseRecord, getWeightRecords, saveWeightRecord } from '../../../api/user/health'
import { ElMessage, ElMessageBox } from 'element-plus'
const tab=ref('diet'), loading=ref(false), dialog=ref(false); const diet=ref<any[]>([]), exercise=ref<any[]>([]), weight=ref<any[]>([])
const dietForm=ref({recordDate:'',mealType:10,foodName:'',calories:0,protein:0,fat:0,carbs:0}); const exerciseForm=ref({recordDate:'',exerciseType:'',duration:30,distance:0,caloriesBurned:0,remark:''}); const weightForm=ref({recordDate:'',weight:60})
const meals=[{label:'早餐',value:10},{label:'午餐',value:20},{label:'晚餐',value:30},{label:'加餐',value:40}]
const fetchData=async()=>{loading.value=true;try{if(tab.value==='diet'){const r=await getDietRecords();diet.value=r.data||[]}else if(tab.value==='exercise'){const r=await getExerciseRecords();exercise.value=r.data||[]}else{const r=await getWeightRecords();weight.value=r.data?.list||r.data||[]}}catch{ElMessage.error('加载健康记录失败')}finally{loading.value=false}}
const open=()=>{dialog.value=true;const d=new Date().toISOString().slice(0,10);if(tab.value==='diet')dietForm.value.recordDate=d;if(tab.value==='exercise')exerciseForm.value.recordDate=d;if(tab.value==='weight')weightForm.value.recordDate=d}
const save=async()=>{try{if(tab.value==='diet')await addDietRecord(dietForm.value as any);else if(tab.value==='exercise')await addExerciseRecord(exerciseForm.value as any);else await saveWeightRecord(weightForm.value as any);ElMessage.success('记录已保存');dialog.value=false;fetchData()}catch{ElMessage.error('保存失败')}}
const remove=async(type:string,id:number)=>{try{await ElMessageBox.confirm('确定删除这条记录吗？','提示');if(type==='diet')await deleteDietRecord(id);else await deleteExerciseRecord(id);fetchData()}catch{}}
onMounted(fetchData)
</script>
<template><div class="page"><div class="panel"><header><div><h3>健康记录</h3><p>记录饮食、运动和体重变化</p></div><el-button type="primary" @click="open">添加记录</el-button></header><el-tabs v-model="tab" @tab-change="fetchData"><el-tab-pane label="饮食" name="diet"><el-table v-loading="loading" :data="diet" border><el-table-column prop="recordDate" label="日期" width="120"/><el-table-column label="餐次" width="90"><template #default="{row}">{{meals.find(m=>m.value===row.mealType)?.label||row.mealType}}</template></el-table-column><el-table-column prop="foodName" label="食物" min-width="150"/><el-table-column prop="calories" label="热量" width="90"/><el-table-column label="营养(g)" min-width="180"><template #default="{row}">蛋白 {{row.protein||0}} · 脂肪 {{row.fat||0}} · 碳水 {{row.carbs||0}}</template></el-table-column><el-table-column label="操作" width="70"><template #default="{row}"><el-button link type="danger" @click="remove('diet',row.id)">删除</el-button></template></el-table-column></el-table></el-tab-pane><el-tab-pane label="运动" name="exercise"><el-table v-loading="loading" :data="exercise" border><el-table-column prop="recordDate" label="日期" width="120"/><el-table-column prop="exerciseType" label="运动类型"/><el-table-column prop="duration" label="时长(分钟)" width="120"/><el-table-column prop="distance" label="距离(km)" width="100"/><el-table-column prop="caloriesBurned" label="消耗热量" width="110"/><el-table-column label="操作" width="70"><template #default="{row}"><el-button link type="danger" @click="remove('exercise',row.id)">删除</el-button></template></el-table-column></el-table></el-tab-pane><el-tab-pane label="体重" name="weight"><el-table v-loading="loading" :data="weight" border><el-table-column prop="recordDate" label="日期" width="150"/><el-table-column prop="weight" label="体重(kg)" width="130"/><el-table-column prop="createTime" label="记录时间"/></el-table></el-tab-pane></el-tabs></div><el-dialog v-model="dialog" :title="tab==='diet'?'添加饮食记录':tab==='exercise'?'添加运动记录':'添加体重记录'" width="540px"><el-form v-if="tab==='diet'" label-width="90px"><el-form-item label="日期"><el-date-picker v-model="dietForm.recordDate" type="date" value-format="YYYY-MM-DD"/></el-form-item><el-form-item label="餐次"><el-select v-model="dietForm.mealType"><el-option v-for="m in meals" :key="m.value" :label="m.label" :value="m.value"/></el-select></el-form-item><el-form-item label="食物名称"><el-input v-model="dietForm.foodName"/></el-form-item><el-form-item label="热量"><el-input-number v-model="dietForm.calories" :min="0"/></el-form-item><el-form-item label="蛋白/脂肪/碳水"><div class="inline"><el-input-number v-model="dietForm.protein" :min="0" :precision="1"/><el-input-number v-model="dietForm.fat" :min="0" :precision="1"/><el-input-number v-model="dietForm.carbs" :min="0" :precision="1"/></div></el-form-item></el-form><el-form v-else-if="tab==='exercise'" label-width="90px"><el-form-item label="日期"><el-date-picker v-model="exerciseForm.recordDate" type="date" value-format="YYYY-MM-DD"/></el-form-item><el-form-item label="运动类型"><el-input v-model="exerciseForm.exerciseType"/></el-form-item><el-form-item label="时长"><el-input-number v-model="exerciseForm.duration" :min="1"/></el-form-item><el-form-item label="距离(km)"><el-input-number v-model="exerciseForm.distance" :min="0" :precision="1"/></el-form-item><el-form-item label="消耗热量"><el-input-number v-model="exerciseForm.caloriesBurned" :min="0"/></el-form-item><el-form-item label="备注"><el-input v-model="exerciseForm.remark" type="textarea"/></el-form-item></el-form><el-form v-else label-width="90px"><el-form-item label="日期"><el-date-picker v-model="weightForm.recordDate" type="date" value-format="YYYY-MM-DD"/></el-form-item><el-form-item label="体重"><el-input-number v-model="weightForm.weight" :min="20" :max="300" :precision="1" :step=".1"/></el-form-item></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" @click="save">保存</el-button></template></el-dialog></div></template>
<style scoped>.page{animation:fadeIn .3s ease}.panel{background:var(--bs-card-bg);border-radius:var(--bs-radius-md);box-shadow:var(--bs-card-shadow);padding:var(--bs-spacing-lg)}header{display:flex;justify-content:space-between;align-items:center;margin-bottom:20px}h3{margin:0;color:var(--bs-text-title)}p{margin:6px 0 0;color:var(--bs-text-muted);font-size:13px}.inline{display:flex;gap:8px}@keyframes fadeIn{from{opacity:0;transform:translateY(10px)}to{opacity:1;transform:translateY(0)}}</style>
